import os

def descargar(base, nombre, leer):
    """Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo."""
    base_abs = os.path.abspath(base)
    ruta = os.path.abspath(os.path.join(base_abs, nombre))
    if not ruta.startswith(base_abs + os.sep) and ruta != base_abs:
        raise PermissionError
    return leer(ruta)

