import os
import os.path

def descargar(base, nombre, leer):
    """Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo."""
    base_abs = os.path.abspath(base)
    ruta_abs = os.path.abspath(os.path.join(base, nombre))

    if not (ruta_abs == base_abs or ruta_abs.startswith(base_abs + os.sep)):
        raise PermissionError("Acceso denegado: intento de acceder a una ruta fuera de la carpeta permitida.")

    if not os.path.isfile(ruta_abs):
        raise PermissionError("El recurso solicitado no existe o no es un archivo.")

    return leer(ruta_abs)

import os
import os.path

def descargar(base, nombre, leer):
    ruta_absoluta = os.path.realpath(os.path.join(base, nombre))
    base_absoluta = os.path.realpath(base)
    if not ruta_absoluta.startswith(base_absoluta + os.sep) and ruta_absoluta != base_absoluta:
        raise PermissionError("Ruta fuera de los límites permitidos")
    return leer(ruta_absoluta)

def leer_archivo(con, usuario, archivo_id):
    """Contenido de un archivo si el usuario es su dueño o es administrador. Si no, None."""
    fila_usuario = con.execute(
        "SELECT rol FROM usuarios WHERE usuario = ?", (usuario,)
    ).fetchone()
    if not fila_usuario:
        return None
    rol = fila_usuario[0]
    if rol == 'administrador':
        fila = con.execute("SELECT contenido FROM archivos WHERE id = ?", (archivo_id,)).fetchone()
        return fila[0] if fila else None
    if rol == 'contratista' or rol == 'analista':
        fila = con.execute(
            "SELECT contenido FROM archivos WHERE id = ? AND propietario = ?", (archivo_id, usuario)
        ).fetchone()
        return fila[0] if fila else None
    return None

def listar_usuarios(con, usuario):
    """Lista de cuentas de la empresa. Solo para administradores: a los demás, PermissionError."""
    cursor = con.execute("SELECT rol FROM usuarios WHERE usuario = ?", (usuario,))
    fila = cursor.fetchone()
    if fila is None:
        raise PermissionError("Usuario no encontrado")
    rol = fila[0]
    if rol != 'administrador':
        raise PermissionError("Acceso denegado: solo administradores")
    return [f[0] for f in con.execute("SELECT usuario FROM usuarios ORDER BY usuario").fetchall()]

import os
import os.path

def descargar(base, nombre, leer):
    """Contenido de un archivo público dentro de la carpeta base. `leer(ruta)` lee un archivo."""
    ruta = os.path.abspath(os.path.join(base, nombre))
    base_abs = os.path.abspath(base)
    # Verificar que la ruta resultante esté dentro de la carpeta base
    if not (ruta == base_abs or ruta.startswith(base_abs + os.sep)):
        raise PermissionError("Acceso denegado: ruta outside de la carpeta base")
    return leer(ruta)
